// Ordering Context
public record OrderCustomer(UUID id, LoyaltyTier tier) {}

// Billing Context
public record BillingCustomer(UUID id, String taxId, BigDecimal limit) {}

public BillingCustomer toDomain(LegacyCrmDto legacy) {
    return new BillingCustomer(
        UUID.fromString(legacy.id()),
        legacy.vatNumber(),
        new BigDecimal(legacy.limit())
    );
}

public OrderSummary getOrderSummary(UUID id) {
    var order = orderClient.findById(id);
    var cust = custClient.findById(order.customerId());

    return new OrderSummary(order, cust);
}

@KafkaListener(topics = "customer.updated")
public void onUpdate(CustomerEvent event) {
    jdbcClient.sql("INSERT ... ON CONFLICT DO UPDATE")
              .param("version", event.version())
              .update();
}
